let global = "I'm global";

function outer() {
  let outerVar = "I'm in outer";

  if (true) {
    let blockVar = "I'm in a block";
    var funcVar = "I'm function-scoped";
    console.log(global);     // ✓ accessible
    console.log(outerVar);   // ✓ accessible
    console.log(blockVar);   // ✓ accessible
  }

  console.log(funcVar);  // ✓ accessible (var is function-scoped)
  // console.log(blockVar); // ✗ ReferenceError (block scope)
}

let a = 1;

function outer() {
  let b = 2;

  function inner() {
    let c = 3;
    console.log(a + b + c);  // 6 — looks up the chain
  }

  inner();
}

outer();

// ✅ Function declaration — fully hoisted
greet();  // works!
function greet() { console.log("Hi!"); }

// ⚠️ var — hoisted but undefined
console.log(x);  // undefined (not an error)
var x = 5;

// ❌ let/const — TDZ, not accessible
// console.log(y);  // ReferenceError!
let y = 10;

// ⚠️ Function expression — same as var
// sayHi();  // TypeError: sayHi is not a function
let sayHi = function() { console.log("Hi!"); };

// TDZ ends at the declaration line
console.log(a);  // ReferenceError!
let a = 5;

// TDZ in if blocks
if (true) {
  console.log(b);  // ReferenceError!
  let b = 10;
}

// TDZ with typeof
console.log(typeof c);  // undefined (typeof is safe for undeclared vars)
// But for let/const it's still a ReferenceError:
// console.log(typeof d); // ReferenceError!
let d = 20;

// No TDZ with var
console.log(e);  // undefined (not an error)
var e = 30;
